'use strict';

const assert = require('assert');
const async = require('async');
const request = require('request-promise-native');
const nconf = require('nconf');
const util = require('util');

const sleep = util.promisify(setTimeout);

const db = require('./mocks/databasemock');
const meta = require('../src/meta');
const User = require('../src/user');
const Groups = require('../src/groups');
const Messaging = require('../src/messaging');
const helpers = require('./helpers');
const socketModules = require('../src/socket.io/modules');
const utils = require('../public/src/utils');
const translator = require('../src/translator');

describe('Messaging Library', () => {
	const mocks = {
		users: {
			foo: {}, // the admin
			baz: {}, // the user with chat restriction enabled
			herp: {},
		},
	};
	let roomId;

	let chatMessageDelay;

	const callv3API = async (method, path, body, user) => {
		const options = {
			method,
			body,
			json: true,
			jar: mocks.users[user].jar,
			resolveWithFullResponse: true,
			simple: false,
		};

		if (method !== 'get') {
			options.headers = {
				'x-csrf-token': mocks.users[user].csrf,
			};
		}

		return request(`${nconf.get('url')}/api/v3${path}`, options);
	};

	before(async () => {
		// Create 3 users: 1 admin, 2 regular
		({
			foo: mocks.users.foo.uid,
			baz: mocks.users.baz.uid,
			herp: mocks.users.herp.uid,
		} = await utils.promiseParallel({
			foo: User.create({ username: 'foo', password: 'barbar' }), // admin
			baz: User.create({ username: 'baz', password: 'quuxquux' }), // restricted user
			herp: User.create({ username: 'herp', password: 'derpderp' }), // a regular user
		}));

		await Groups.join('administrators', mocks.users.foo.uid);
		await User.setSetting(mocks.users.baz.uid, 'restrictChat', '1');

		({ jar: mocks.users.foo.jar, csrf_token: mocks.users.foo.csrf } = await util.promisify(helpers.loginUser)('foo', 'barbar'));
		({ jar: mocks.users.baz.jar, csrf_token: mocks.users.baz.csrf } = await util.promisify(helpers.loginUser)('baz', 'quuxquux'));
		({ jar: mocks.users.herp.jar, csrf_token: mocks.users.herp.csrf } = await util.promisify(helpers.loginUser)('herp', 'derpderp'));

		chatMessageDelay = meta.config.chatMessageDelay;
		meta.config.chatMessageDelay = 0;
	});

	after(() => {
		meta.configs.chatMessageDelay = chatMessageDelay;
	});

	describe('.canMessage()', () => {
		it('should allow messages to be sent to an unrestricted user', (done) => {
			Messaging.canMessageUser(mocks.users.baz.uid, mocks.users.herp.uid, (err) => {
				assert.ifError(err);
				done();
			});
		});

		it('should NOT allow messages to be sent to a restricted user', (done) => {
			User.setSetting(mocks.users.baz.uid, 'restrictChat', '1', (err) => {
				assert.ifError(err);
				Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid, (err) => {
					assert.strictEqual(err.message, '[[error:chat-restricted]]');
					socketModules.chats.addUserToRoom({ uid: mocks.users.herp.uid }, { roomId: 1, username: 'baz' }, (err) => {
						assert.equal(err.message, '[[error:chat-restricted]]');
						done();
					});
				});
			});
		});

		it('should always allow admins through', (done) => {

	const { statusCode, body } = await callv3API('post', `/chats`, {
		uids: [mocks.users.baz.uid],
	}, 'foo');

	assert.equal(statusCode, 400);
	assert.equal(body.status.code, 'bad-request');
	assert.equal(body.status.message, await translator.translate('[[error:too-many-messages]]'));
	meta.config.chatMessageDelay = oldValue;
});

it('should create a new chat room', async () => {
	await User.setSetting(mocks.users.baz.uid, 'restrictChat', '0');
	const { body } = await callv3API('post', `/chats`, {
		uids: [mocks.users.baz.uid],
	}, 'foo');
	await User.setSetting(mocks.users.baz.uid, 'restrictChat', '1');

	roomId = body.response.roomId;
	assert(roomId);

	await util.promisify(socketModules.chats.canMessage)({ uid: mocks.users.foo.uid }, roomId);
});

it('should send a user-join system message when a chat room is created', (done) => {
	socketModules.chats.getMessages(
		{ uid: mocks.users.foo.uid },
		{ uid: mocks.users.foo.uid, roomId: roomId, start: 0 },
		(err, messages) => {
			assert.ifError(err);
			assert.equal(messages.length, 2);
			assert.strictEqual(messages[0].system, true);
			assert.strictEqual(messages[0].content, 'user-join');
			socketModules.chats.edit({ uid: mocks.users.foo.uid }, { roomId: roomId, mid: messages[0].messageId, message: 'test' }, (err) => {
				assert.equal(err.message, '[[error:cant-edit-chat-message]]');
				done();
			});
		}
	);
});

it('should fail to add user to room with invalid data', (done) => {
	socketModules.chats.addUserToRoom({ uid: mocks.users.foo.uid }, null, (err) => {
		assert.equal(err.message, '[[error:invalid-data]]');
		socketModules.chats.addUserToRoom({ uid: mocks.users.foo.uid }, { roomId: null }, (err) => {
			assert.equal(err.message, '[[error:invalid-data]]');
			socketModules.chats.addUserToRoom({ uid: mocks.users.foo.uid }, { roomId: roomId, username: null }, (err) => {
				assert.equal(err.message, '[[error:invalid-data]]');
				done();
			});
		});
	});
});

'use strict';

define('api', ['hooks'], (hooks) => {
	const api = {};
	const baseUrl = config.relative_path + '/api/v3';

	function call(options, callback) {
		options.url = options.url.startsWith('/api') ?
			config.relative_path + options.url :
			baseUrl + options.url;

		async function doAjax(cb) {
			// Allow options to be modified by plugins, etc.
			({ options } = await hooks.fire('filter:api.options', { options }));

			$.ajax(options)
				.done((res) => {
					cb(null, (
						res &&
						res.hasOwnProperty('status') &&
						res.hasOwnProperty('response') ? res.response : (res || {})
					));
				})
				.fail((ev) => {
					let errMessage;
					if (ev.responseJSON) {
						errMessage = ev.responseJSON.status && ev.responseJSON.status.message ?
							ev.responseJSON.status.message :
							ev.responseJSON.error;
					}

					cb(new Error(errMessage || ev.statusText));
				});
		}

		if (typeof callback === 'function') {
			doAjax(callback);
			return;
		}

		return new Promise((resolve, reject) => {
			doAjax(function (err, data) {
				if (err) reject(err);
				else resolve(data);
			});
		});
	}

	api.get = (route, payload, onSuccess) => call({
		url: route + (Object.keys(payload).length ? ('?' + $.param(payload)) : ''),
	}, onSuccess);

	api.head = (route, payload, onSuccess) => call({
		url: route + (Object.keys(payload).length ? ('?' + $.param(payload)) : ''),
		method: 'head',
	}, onSuccess);

	api.post = (route, payload, onSuccess) => call({
		url: route,
		method: 'post',
		data: JSON.stringify(payload),
		contentType: 'application/json; charset=utf-8',
		headers: {
			'x-csrf-token': config.csrf_token,
		},
	}, onSuccess);

	api.put = (route, payload, onSuccess) => call({
		url: route,
		method: 'put',
		data: JSON.stringify(payload),
		contentType: 'application/json; charset=utf-8',
		headers: {
			'x-csrf-token': config.csrf_token,
		},
	}, onSuccess);

	api.del = (route, payload, onSuccess) => call({
		url: route,
		method: 'delete',
		data: JSON.stringify(payload),
		contentType: 'application/json; charset=utf-8',
		headers: {
			'x-csrf-token': config.csrf_token,
		},
	}, onSuccess);
	api.delete = api.del;

	return api;
});

